(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.022+t*0.4)*8 + Math.cos(mx*0.017-t*0.35)*6;
  const w2y = Math.cos(mx*0.025-t*0.32)*7 + Math.sin(my*0.02+t*0.45)*5;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*100, 170+Math.sin(t*0.6)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*95, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*95, 50+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+4)*45, 0.1, 1.9, 0.8],
    [420+Math.cos(t*0.42+1)*60, 200+Math.sin(t*0.65+2)*55, 0.07, 2.2, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f-t*sp);
    aS += wv*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.1)*w*0.5;
  }
  const n=src.reduce((a,s)=>a+s[4],0);
  aS/=n; iS/=n; cS/=n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.11+t*2.2)*0.18
    +Math.sin((sx-sy)*0.09-t*1.8)*0.18
    +Math.sin(sx*0.06+sy*0.02-t*1.5)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const sp2=Math.sin(dist*0.02-ang*2-t*0.8)*0.2+Math.sin(dist*0.06+ang*5-t*2.0)*0.15;
  const cross=Math.sin((sx*0.08+t*0.5))*(Math.sin(sy*0.08-t*0.4))*0.3;
  const lap = (Math.sin((sx+2)*0.15)*Math.sin(sy*0.15)+Math.sin((sx-2)*0.15)*Math.sin(sy*0.15)
    +Math.sin(sx*0.15)*Math.sin((sy+2)*0.15)+Math.sin(sx*0.15)*Math.sin((sy-2)*0.15)
    -4*Math.sin(sx*0.15)*Math.sin(sy*0.15))*0.5;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+lap*0.3)*1.6)*0.28;
  const reaction=Math.tanh((aS-iS*0.65+bg*0.25+sp1+sp2+cross*0.5+cS*0.3)*2.0);
  const rd=Math.tanh((reaction*1.5-cell*0.8+iS*0.4)*1.8);
  const pulse=0.92+Math.sin(t*0.6)*0.08;
  const blend=rd*0.65+cell*0.2+reaction*0.15;
  const v=Math.max(0,Math.min(1,blend*0.5*pulse+0.5));
  const pal=[
    [5,12,52],[12,45,95],[18,85,120],[25,130,135],
    [80,165,120],[170,190,80],[220,175,60],[215,130,55],
    [195,80,65],[155,45,70],[90,25,65],[35,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(rd*Math.PI)*0.18;
  const edge=Math.abs(rd)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(rd)*2.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*180))|0
  ];
}
